/* ============================================================
   REWRITE RULES + QUERY VARS
   ============================================================ */
add_action( 'init', function() {
    // Matrix rule (explicit service alternation, 'top' priority to beat city CPT regex)
    add_rewrite_rule(
        '^([a-z][a-z0-9-]*)-(refrigerator|washing-machine|dishwasher|dryer|oven|stove|freezer|gas-appliance)-repair/?$',
        'index.php?caspian_svc=$matches[2]&caspian_city=$matches[1]',
        'top'
    );
}, 11 );

add_filter( 'query_vars', function( $vars ) {
    $vars[] = 'caspian_svc';
    $vars[] = 'caspian_city';
    return $vars;
});

/* ============================================================
   CITY LOOKUP — try multiple CPT names + fallback
   ============================================================ */
function caspian_matrix_get_city( $city_slug ) {
    $candidates = array( 'city', 'caspian_city', 'cities' );
    foreach ( $candidates as $cpt ) {
        if ( ! post_type_exists( $cpt ) ) continue;
        // City CPT post name is typically "<slug>-appliance-repair"
        $p = get_page_by_path( $city_slug . '-appliance-repair', OBJECT, $cpt );
        if ( $p && $p->post_status === 'publish' ) return $p;
        // Fallback: just the slug
        $p = get_page_by_path( $city_slug, OBJECT, $cpt );
        if ( $p && $p->post_status === 'publish' ) return $p;
    }
    // Last-resort generic lookup
    $posts = get_posts( array(
        'post_type'      => 'any',
        'name'           => $city_slug . '-appliance-repair',
        'numberposts'    => 1,
        'post_status'    => 'publish',
        'suppress_filters' => false,
    ));
    return $posts ? $posts[0] : null;
}

/* Pull a clean city name out of the post title (strip trailing "appliance repair") */
function caspian_matrix_city_name( $city_post ) {
    $name = $city_post->post_title;
    $name = preg_replace( '/\s*appliance\s*repair\s*$/i', '', $name );
    $name = trim( $name );
    return $name ?: $city_post->post_title;
}

/* City slug -> city URL (e.g. "hamilton" -> "/hamilton-appliance-repair/") */
function caspian_matrix_city_url( $city_slug ) {
    return '/' . sanitize_title( $city_slug ) . '-appliance-repair/';
}

/* ============================================================
   GLOBAL CONTEXT (set by intercept; used by filters/schema)
   ============================================================ */
global $caspian_matrix_ctx;
$caspian_matrix_ctx = null;

/* ============================================================
   TEMPLATE REDIRECT — DIRECT RENDER
   Bypasses WP template hierarchy. get_header + echo + get_footer + exit.
   Same pattern as brand pages. No virtual post (fatal incompat with Yoast/Astra).
   ============================================================ */
add_action( 'template_redirect', 'caspian_matrix_intercept', 5 );

function caspian_matrix_intercept() {
    $svc_key   = get_query_var( 'caspian_svc' );
    $city_slug = get_query_var( 'caspian_city' );

    if ( empty( $svc_key ) || empty( $city_slug ) ) return;

    $services = caspian_matrix_services();
    if ( ! isset( $services[ $svc_key ] ) ) return;

    $city = caspian_matrix_get_city( $city_slug );
    if ( ! $city ) {
        // City not found -> 404
        global $wp_query;
        $wp_query->set_404();
        status_header( 404 );
        nocache_headers();
        return;
    }

    $svc        = $services[ $svc_key ];
    $city_name  = caspian_matrix_city_name( $city );
    $appliance  = $svc['label'];
    $page_title = $appliance . ' Repair in ' . $city_name;

    // Set global context for Yoast filters + FAQ schema
    global $caspian_matrix_ctx, $wp_query;
    $caspian_matrix_ctx = array(
        'city'      => $city,
        'city_name' => $city_name,
        'city_slug' => $city_slug,
        'svc_key'   => $svc_key,
        'svc'       => $svc,
        'appliance' => $appliance,
        'title'     => $page_title,
    );

    // Tell WP this is NOT a 404
    $wp_query->is_404 = false;
    status_header( 200 );
    nocache_headers();

    // FAQ schema in head
    add_action( 'wp_head', 'caspian_matrix_faq_schema', 50 );

    // Document title override (Astra/WP core)
    add_filter( 'document_title_parts', function( $parts ) use ( $page_title ) {
        $parts['title'] = $page_title;
        unset( $parts['tagline'] );
        return $parts;
    }, 99 );
    add_filter( 'pre_get_document_title', function( $title ) use ( $page_title ) {
        return $page_title . ' | Caspian Appliance Repair';
    }, 99 );

    // Suppress Astra page title bar (we render own hero)
    add_filter( 'astra_the_title_enabled', '__return_false', 999 );

    // Force Astra to render no-sidebar + page-builder (full-width) layout for matrix pages.
    // Without this, virtual-page rendering can fall into a default sidebar layout,
    // leaving the right half of the viewport empty.
    add_filter( 'astra_page_layout',                                  function() { return 'no-sidebar'; },   9999 );
    add_filter( 'astra_sidebar_layout',                               function() { return 'no-sidebar'; },   9999 );
    add_filter( 'astra_get_option_site-sidebar-layout',               function() { return 'no-sidebar'; },   9999 );
    add_filter( 'astra_get_option_single-page-sidebar-layout',        function() { return 'no-sidebar'; },   9999 );
    add_filter( 'astra_get_option_single-post-sidebar-layout',        function() { return 'no-sidebar'; },   9999 );
    add_filter( 'astra_get_content_layout',                           function() { return 'page-builder'; }, 9999 );
    add_filter( 'astra_get_option_site-content-layout',               function() { return 'page-builder'; }, 9999 );
    add_filter( 'astra_get_option_single-page-content-layout',        function() { return 'page-builder'; }, 9999 );
    add_filter( 'astra_get_option_single-post-content-layout',        function() { return 'page-builder'; }, 9999 );
    // Belt-and-suspenders body classes
    add_filter( 'body_class', function( $classes ) {
        $classes[] = 'ast-no-sidebar';
        $classes[] = 'ast-page-builder-template';
        $classes[] = 'ast-single-post';
        $classes[] = 'caspian-matrix-body';
        return $classes;
    }, 9999 );

    // Direct render — no virtual post, no the_content filter
    try {
        get_header();
        echo caspian_matrix_render( $caspian_matrix_ctx );
        get_footer();
    } catch ( Throwable $e ) {
        error_log( 'CASPIAN-MATRIX render error on /' . $city_slug . '-' . $svc_key . '-repair/: ' . $e->getMessage() . ' @ ' . $e->getFile() . ':' . $e->getLine() );
        echo '<div style="max-width:800px;margin:60px auto;padding:30px;background:#f9f9f9;border:1px solid #ddd;border-radius:6px;text-align:center;">';
        echo '<h2 style="color:#062963;">' . esc_html( $page_title ) . '</h2>';
        echo '<p>For service, please call <a href="tel:+14167325905" style="color:#0B3D91;font-weight:600;">(416) 732-5905</a>.</p>';
        echo '</div>';
    }
    exit;
}

/* ============================================================
   YOAST META TITLE / DESCRIPTION
   ============================================================ */
add_filter( 'wpseo_title', function( $title ) {
    global $caspian_matrix_ctx;
    if ( ! $caspian_matrix_ctx ) return $title;
    return sprintf( '%s %s Repair | Same-Day Service | Caspian',
        $caspian_matrix_ctx['city_name'],
        $caspian_matrix_ctx['appliance']
    );
}, 99 );

add_filter( 'wpseo_metadesc', function( $desc ) {
    global $caspian_matrix_ctx;
    if ( ! $caspian_matrix_ctx ) return $desc;
    return sprintf(
        'Same-day %s repair in %s by local technicians. All major brands. BBB A Accredited, ★4.8/220+ Google Reviews. 90-day warranty. Call (416) 732-5905.',
        strtolower( $caspian_matrix_ctx['svc']['label'] ),
        $caspian_matrix_ctx['city_name']
    );
}, 99 );

add_filter( 'wpseo_canonical', function( $canon ) {
    global $caspian_matrix_ctx;
    if ( ! $caspian_matrix_ctx ) return $canon;
    return home_url( '/' . $caspian_matrix_ctx['city_slug'] . '-' . $caspian_matrix_ctx['svc_key'] . '-repair/' );
}, 99 );

add_filter( 'wpseo_opengraph_url', function( $url ) {
    global $caspian_matrix_ctx;
    if ( ! $caspian_matrix_ctx ) return $url;
    return home_url( '/' . $caspian_matrix_ctx['city_slug'] . '-' . $caspian_matrix_ctx['svc_key'] . '-repair/' );
}, 99 );

/* ============================================================
   FAQ SCHEMA (JSON-LD in head)
   ============================================================ */
function caspian_matrix_faq_schema() {
    global $caspian_matrix_ctx;
    if ( ! $caspian_matrix_ctx ) return;

    $faqs = caspian_matrix_faqs( $caspian_matrix_ctx );
    if ( empty( $faqs ) ) return;

    $items = array();
    foreach ( $faqs as $f ) {
        $items[] = array(
            '@type'          => 'Question',
            'name'           => $f['q'],
            'acceptedAnswer' => array(
                '@type' => 'Answer',
                'text'  => wp_strip_all_tags( $f['a'] ),
            ),
        );
    }
    $schema = array(
        '@context'   => 'https://schema.org',
        '@type'      => 'FAQPage',
        'mainEntity' => $items,
    );
    echo "\n<script type=\"application/ld+json\">" . wp_json_encode( $schema, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE ) . "</script>\n";
}

/* Generate 6 FAQs unique to this city+service combo */
function caspian_matrix_faqs( $ctx ) {
    $city      = $ctx['city_name'];
    $appliance = $ctx['appliance'];
    $applow    = strtolower( $appliance );
    $is_gas    = ! empty( $ctx['svc']['tssa'] );

    $faqs = array(
        array(
            'q' => sprintf( 'Do you repair %s in %s?', $applow, $city ),
            'a' => sprintf( 'Yes — Caspian technicians serve %s every day, with same-day appointments often available. We work on all major %s brands including Samsung, LG, Whirlpool, KitchenAid, Bosch, Maytag, Frigidaire, GE, and more.', $city, $applow ),
        ),
        array(
            'q' => sprintf( 'How much does %s repair cost in %s?', $applow, $city ),
            'a' => sprintf( 'Pricing is quoted in writing after on-site diagnosis. Each %s repair is different — element replacement on an oven, for example, is very different from a sealed-system fridge repair. Our technician will diagnose the issue and give you a firm price before any work begins.', $applow ),
        ),
        array(
            'q' => sprintf( 'What %s brands do you service in %s?', $applow, $city ),
            'a' => sprintf( 'We service all major %s brands in %s: Samsung, LG, Whirlpool, KitchenAid, Bosch, Maytag, Frigidaire, GE, Kenmore, Electrolux, Amana, Jenn-Air, Thermador, Viking, Wolf, and Fisher & Paykel. We are independent and not factory-authorized for warranty work — we provide quality out-of-warranty repairs.', $applow, $city ),
        ),
        array(
            'q' => sprintf( 'Do you offer same-day %s repair in %s?', $applow, $city ),
            'a' => sprintf( 'Yes — same-day %s service in %s is available most days, subject to technician availability and parts on hand. Call (416) 732-5905 or book online and our dispatch will confirm the soonest slot.', $applow, $city ),
        ),
        array(
            'q' => 'Are you BBB Accredited?',
            'a' => 'Yes, Caspian Appliance Repair is BBB A Accredited (Hamilton, ON). You can view our profile and complaint history on the Better Business Bureau website.',
        ),
        array(
            'q' => sprintf( 'Do you offer a warranty on %s repairs?', $applow ),
            'a' => 'Yes — every repair is backed by a 90-day parts and labour warranty. If the same issue returns within 90 days, we return at no charge.',
        ),
    );

    if ( $is_gas ) {
        $faqs[] = array(
            'q' => sprintf( 'Are your technicians TSSA-licensed for gas %s repair?', $applow ),
            'a' => sprintf( 'Yes — all gas-line work on %s in %s is performed by TSSA-licensed partner technicians, in compliance with Ontario regulations.', $applow, $city ),
        );
    }

    return $faqs;
}

/* ============================================================
   RENDER — main template
   ============================================================ */
function caspian_matrix_render( $ctx ) {
    $city       = $ctx['city'];
    $city_name  = $ctx['city_name'];
    $city_slug  = $ctx['city_slug'];
    $svc        = $ctx['svc'];
    $svc_key    = $ctx['svc_key'];
    $appliance  = $ctx['appliance'];
    $applow     = strtolower( $appliance );
    $applow_one = $svc['label_short'];
    $is_gas     = ! empty( $svc['tssa'] );

    $city_intro = function_exists( 'get_field' ) ? get_field( 'city_intro', $city->ID ) : '';
    $city_intro = is_string( $city_intro ) ? trim( $city_intro ) : '';

    $brand_logos = function_exists( 'caspian_brand_logos' ) ? caspian_brand_logos() : array();
    $brands      = caspian_matrix_brands();
    $faqs        = caspian_matrix_faqs( $ctx );

    /* Internal-link matrix data */
    $other_services = array();
    foreach ( caspian_matrix_services() as $k => $s ) {
        if ( $k === $svc_key ) continue;
        $other_services[] = array(
            'url'   => '/' . $city_slug . '-' . $k . '-repair/',
            'label' => $s['label'] . ' Repair',
        );
    }

    /* Nearby cities for SAME service */
    $nearby_cities = array();
    if ( function_exists( 'get_field' ) ) {
        $nearby = get_field( 'nearby_cities', $city->ID );
        if ( is_array( $nearby ) ) {
            foreach ( $nearby as $nb ) {
                $nb_post = is_object( $nb ) ? $nb : get_post( $nb );
                if ( ! $nb_post ) continue;
                $nb_name = caspian_matrix_city_name( $nb_post );
                $nb_slug = preg_replace( '/-appliance-repair$/', '', $nb_post->post_name );
                $nearby_cities[] = array(
                    'url'   => '/' . $nb_slug . '-' . $svc_key . '-repair/',
                    'label' => $appliance . ' Repair in ' . $nb_name,
                );
            }
        }
    }
    /* Fallback: use caspian_city_nearby_fallback() if available and ACF empty */
    if ( empty( $nearby_cities ) && function_exists( 'caspian_city_nearby_fallback' ) ) {
        $fb = caspian_city_nearby_fallback( $city_slug );
        if ( is_array( $fb ) ) {
            foreach ( array_slice( $fb, 0, 8 ) as $row ) {
                if ( empty( $row['slug'] ) ) continue;
                $nearby_cities[] = array(
                    'url'   => '/' . $row['slug'] . '-' . $svc_key . '-repair/',
                    'label' => $appliance . ' Repair in ' . ( $row['name'] ?? $row['slug'] ),
                );
            }
        }
    }

    ob_start();
    ?>
